<script>window.BlacklistedExperiments = ["afb"]</script>
<script>window.catalogPageStatus = 200</script>
<script>
    const CATALOG_PAGE_INFO = {
      HOME: "home",
      PLP: "plp",
      PDP: "pdp",
      EXPLORE: "explore",
      SPECIALTY_STORE: "specialty store",
      NEW: "new",
      TRIAL: "trial",
      BEST_SELLING: "best selling",
      SPECIALS: "specials",
      SEARCH: "search",
      BLOG_HOME: "blog home",
      BLOG_ARTICLE: "blog article",
      BLOG_CATEGORY: "blog category",
      BLOG_SEARCH: "blog search",
      EXPERTS: "blog experts",
      INFLUENCER: "influencer",
      REWARDS: "rewards",
      COMPANY_INFO: "company info",
      CUSTOMER_SERVICE: "customer service",
      OTHER: "other",
      UGC: "ugc",
    };

    const pagePaths = {
      home: "/",
      recent: "/new-products",
      trial: "/trial-pricing",
      topsellers: "/catalog/topsellers",
      specials: "/specials",
      search: "/search",
      blog: "/blog",
      blogSearch: "/blog/search",
      aboutUs: "/info/about",
      vendors: "/info/vendors",
      influencers: "/info/influencers",
      rewardsProgram: "/info/rewards-program",
      contact: "/help/contact",
    };

    function getPageType(pathname) {
      if (!pathname) {
        return CATALOG_PAGE_INFO.OTHER;
      }

      switch (pathname) {
        case pagePaths.home:
          return CATALOG_PAGE_INFO.HOME;
        case pagePaths.recent:
          return CATALOG_PAGE_INFO.NEW;
        case pagePaths.trial:
          return CATALOG_PAGE_INFO.TRIAL;
        case pagePaths.topsellers:
          return CATALOG_PAGE_INFO.BEST_SELLING;
        case pagePaths.specials:
          return CATALOG_PAGE_INFO.SPECIALS;
        case pagePaths.search:
          return CATALOG_PAGE_INFO.SEARCH;
        case pagePaths.blog:
          return CATALOG_PAGE_INFO.BLOG_HOME;
        case pagePaths.blogSearch:
          return CATALOG_PAGE_INFO.BLOG_SEARCH;
        case pagePaths.aboutUs:
        case pagePaths.vendors:
          return CATALOG_PAGE_INFO.COMPANY_INFO;
        case pagePaths.influencers:
          return CATALOG_PAGE_INFO.INFLUENCER;
        case pagePaths.rewardsProgram:
          return CATALOG_PAGE_INFO.REWARDS;
        case pagePaths.contact:
          return CATALOG_PAGE_INFO.CUSTOMER_SERVICE;
        default:
          break;
      }

      if (pathname.includes("pr/index.html")) {
        return CATALOG_PAGE_INFO.PDP;
      } else if (pathname.includes("c/index.html")) {
        return CATALOG_PAGE_INFO.PLP;
      } else if (pathname.includes("hs/index.html")) {
        return CATALOG_PAGE_INFO.SPECIALTY_STORE;
      } else if (pathname.includes("blog/index.html")) {
        if (pathname.split("index.html").length > 3) {
          return CATALOG_PAGE_INFO.BLOG_ARTICLE;
        }
        return CATALOG_PAGE_INFO.BLOG_CATEGORY;
      } else if (pathname.includes("/experts")) {
        return CATALOG_PAGE_INFO.EXPERTS;
      }
      else if (pathname.includes("r/index.html") || pathname.includes("ugc/index.html")) {
        return CATALOG_PAGE_INFO.UGC;
      } else if (pathname.includes("shipping/index.html")) {
        return CATALOG_PAGE_INFO.COMPANY_INFO;
      }

      return CATALOG_PAGE_INFO.OTHER;
    };

    function getPageCategory(pathname) {
      if (!pathname) {
        return CATALOG_PAGE_INFO.OTHER;
      }

      switch (pathname) {
        case pagePaths.home:
          return CATALOG_PAGE_INFO.HOME;
        case pagePaths.recent:
        case pagePaths.trial:
        case pagePaths.specials:
        case pagePaths.search:
          return CATALOG_PAGE_INFO.PLP;
        default:
          break;
      }

      if (pathname.includes("pr/index.html")) {
        return CATALOG_PAGE_INFO.PDP;
      } else if (pathname.includes("c/index.html")) {
        return CATALOG_PAGE_INFO.PLP;
      } else if (pathname.includes("/blog") || pathname.includes("/experts")) {
        return "blog";
      } else if (pathname.includes("r/index.html") || pathname.includes("ugc/index.html")) {
        return CATALOG_PAGE_INFO.UGC;
      }
      return CATALOG_PAGE_INFO.OTHER;
    };
</script>
<script>
  (function () {
    function getCookie(cookieName) {
      try {
        const cookies = document.cookie.split("; ");
        for (const cookie of cookies) {
          const [name, value] = cookie.split("=");
          if (name.trim() === cookieName) {
            return atob(decodeURIComponent(value));
          }
        }
        return null;
      } catch (error) {
        console.error("Failed to parse cookie:", error);
        return null;
      }
    }

    function parseExperiments(cookieValue) {
      try {
        const experiments = JSON.parse(cookieValue);
        const whitelistedSources = (window.ExperimentSourceWhitelist || "")
          .split(",")
          .map(Number);
        const blacklistedExperiments = window.BlacklistedExperiments || [];

        return Object.entries(experiments)
          .filter(
            ([key, exp]) =>
              !blacklistedExperiments.includes(key) &&
              whitelistedSources.includes(exp.Source),
          )
          .map(([key, exp]) => `${key}=${exp.ChosenVariant ?? exp.Var}`)
          .join(",");
      } catch (error) {
        console.error("Failed to parse experiments:", error);
        return null;
      }
    }

    const experimentCookieValue = getCookie("ih-experiment");
    if (!experimentCookieValue) {
      console.log("Cookie has no value or does not exist");
      return;
    }

    const experimentValuesString = parseExperiments(experimentCookieValue);
    if (!experimentValuesString) return;

    let searchActiveExperiment = "";
    if (
      window.activeSearchExperimentVariants &&
      typeof window.activeSearchExperimentVariants === "object"
    ) {
      searchActiveExperiment = Object.entries(
        window.activeSearchExperimentVariants,
      )
        .map(([key, value]) => `${key}=${value}`)
        .join(",");
    }
    let categoryName = window.CATEGORY_ID;
    let urlName = window.URL_NAME;
    let content_group = "catalog";

    let content_group2 = !!window.PLP_PAGE_TYPE ? !!window.IS_STORE_LANDING ? "store":"plp" : "";

    if (window.getPageCategory && !window.PLP_PAGE_TYPE) {
      content_group2 = window.getPageCategory(document.location.pathname);
    }

    let content_group3 = !!window.PLP_PAGE_TYPE ? window.PLP_PAGE_TYPE : "";

    if (window.getPageType && !window.PLP_PAGE_TYPE) {
      content_group3 = window.getPageType(document.location.pathname);
    }

    (window.dataLayer = window.dataLayer || []).push({
      event: "page_content",
      page_content: {
        category: {
          id: categoryName || "",
          name: urlName || "",
        },
        content_group: content_group,
        content_group2: content_group2,
        content_group3: content_group3,
        page_title: "",
        page_type: !!window.PLP_PAGE_TYPE ? window.PLP_PAGE_TYPE : "",
        internal_referrer: "",
        recommended_experience: experimentValuesString,
        search_active_experiment: searchActiveExperiment,
        page_status: window.catalogPageStatus || 200,
      },
    });
  })();
</script>
